// Accept an Alertmanager receiver generated by the platform. The returned Secret
// should be piped directly to kubectl (the receiver includes a credential).
import { webhook } from '../server/manifest.js';
import { ensure, origin } from '../server/common.js';
export const images = {
  prometheus:
    'prom/prometheus:v3.13.5@sha256:aafa9d694e6a883c02db516d9f6e5b84e14195f49a2a6456a4cca815edda72b9',
  alertmanager:
    'prom/alertmanager:v0.35.0@sha256:e638797febd034838eca8b98cdbd46f951e9bf7f178777aa8669167406a9946c',
  blackbox:
    'prom/blackbox-exporter:v0.29.1@sha256:ea1c7aa3ef3f307cd03e85f34abb604478ccb90b567fc690da0cd9776da76b13',
};
export function monitoring(
  receiver,
  target = 'http://demo-web.kube-agent-lab.svc/',
  namespace = 'kubepilot-monitoring',
) {
  const normalized =
    typeof receiver === 'string' ? receiver.replace(/\r\n/g, '\n').replace(/\n+$/, '') : '';
  const lines = normalized.split('\n');
  const rawURL = lines[3]?.match(/^      - url: "([^"]+)"$/)?.[1];
  const token = lines[8]?.match(/^            credentials: "([A-Za-z0-9_-]{25,128})"$/)?.[1];
  ensure(rawURL && token, '接收配置无效');
  const u = new URL(rawURL);
  const cfg = { publicUrl: origin(u.origin, true), webhookToken: token };
  ensure(webhook(cfg) === normalized, '请使用平台生成的完整接收配置');
  const receivers = [
    {
      name: 'kubepilot',
      webhook_configs: [
        {
          url: cfg.publicUrl + '/ingest/alertmanager',
          send_resolved: true,
          http_config: { authorization: { type: 'Bearer', credentials: token } },
        },
      ],
    },
  ];
  const meta = (name) => ({ name, namespace }),
    items = [{ apiVersion: 'v1', kind: 'Namespace', metadata: { name: namespace } }];
  const create = (kind, name, extra, apiVersion = 'v1') =>
    items.push({ apiVersion, kind, metadata: meta(name), ...extra });
  const config = {
    prometheus: {
      'prometheus.yml': JSON.stringify({
        global: { scrape_interval: '3s', evaluation_interval: '3s' },
        alerting: { alertmanagers: [{ static_configs: [{ targets: ['alertmanager:9093'] }] }] },
        rule_files: ['/cfg/rules.yml'],
        scrape_configs: [
          {
            job_name: 'application',
            metrics_path: '/probe',
            params: { module: ['http_2xx'] },
            static_configs: [{ targets: [target] }],
            relabel_configs: [
              { source_labels: ['__address__'], target_label: '__param_target' },
              { source_labels: ['__param_target'], target_label: 'instance' },
              { target_label: '__address__', replacement: 'blackbox:9115' },
            ],
          },
        ],
      }),
      'rules.yml': JSON.stringify({
        groups: [
          {
            name: 'kubepilot',
            rules: [
              {
                alert: 'KubePilotBusinessUnavailable',
                expr: 'probe_success{job="application"} == 0',
                for: '3s',
                labels: { severity: 'warning' },
                annotations: { summary: '业务 HTTP 探测失败' },
              },
            ],
          },
        ],
      }),
    },
    alertmanager: {
      'alertmanager.yml': JSON.stringify({
        route: { receiver: 'kubepilot', group_wait: '1s', group_interval: '3s', repeat_interval: '1h' },
        receivers,
      }),
    },
    blackbox: {
      'blackbox.yml': JSON.stringify({
        modules: { http_2xx: { prober: 'http', timeout: '2s', http: { preferred_ip_protocol: 'ip4' } } },
      }),
    },
  };
  const ports = { prometheus: 9090, alertmanager: 9093, blackbox: 9115 };
  for (const [name, image] of Object.entries(images)) {
    const secret = name === 'alertmanager',
      dir = '/data',
      labels = { app: name };
    create(
      secret ? 'Secret' : 'ConfigMap',
      name,
      secret ? { type: 'Opaque', stringData: config[name] } : { data: config[name] },
    );
    const args = ['--config.file=/cfg/' + name + '.yml'];
    if (name === 'prometheus')
      args.push('--storage.tsdb.path=' + dir, '--storage.tsdb.retention.time=6h');
    if (name === 'alertmanager') args.push('--storage.path=' + dir, '--cluster.listen-address=');
    const probe = (path) => ({
      httpGet: { path, port: ports[name] },
      periodSeconds: 5,
      timeoutSeconds: 3,
    });
    create(
      'Deployment',
      name,
      {
        spec: {
          replicas: 1,
          selector: { matchLabels: labels },
          template: {
            metadata: { labels },
            spec: {
              automountServiceAccountToken: false,
              securityContext: {
                runAsNonRoot: true,
                runAsUser: 65534,
                fsGroup: 65534,
                seccompProfile: { type: 'RuntimeDefault' },
              },
              volumes: [
                {
                  name: 'cfg',
                  ...(secret ? { secret: { secretName: name } } : { configMap: { name } }),
                },
                { name: 'storage', emptyDir: {} },
              ],
              containers: [
                {
                  name,
                  image,
                  imagePullPolicy: 'IfNotPresent',
                  args,
                  ports: [{ containerPort: ports[name] }],
                  securityContext: {
                    readOnlyRootFilesystem: true,
                    allowPrivilegeEscalation: false,
                    capabilities: { drop: ['ALL'] },
                  },
                  volumeMounts: [
                    { name: 'cfg', mountPath: '/cfg', readOnly: true },
                    { name: 'storage', mountPath: dir },
                  ],
                  readinessProbe: probe(name === 'blackbox' ? '/-/healthy' : '/-/ready'),
                  livenessProbe: probe('/-/healthy'),
                  startupProbe: { ...probe('/-/healthy'), failureThreshold: 30 },
                },
              ],
            },
          },
        },
      },
      'apps/v1',
    );
    create('Service', name, {
      spec: { selector: labels, ports: [{ port: ports[name], targetPort: ports[name] }] },
    });
  }
  return { apiVersion: 'v1', kind: 'List', items };
}
